/// Elevation.
///
/// SwiftUI stacks `.shadow` modifiers, so the drops reproduce faithfully. The
/// 1px hairline ring does not: it becomes a stroked overlay, which is visually
/// equivalent but is drawn inside the frame rather than outside it.
///
///     RoundedRectangle(cornerRadius: F055Radius.xl)
///         .fill(palette.card)
///         .f055CardElevation(ring: palette.border, radius: F055Radius.xl)
public enum F055Elevation {
    public struct Drop {
        public let color: Color
        public let radius: CGFloat
        public let y: CGFloat
    }

    /// Both drops of the `card` and `thumb` levels (Tailwind shadow-sm).
    public static let cardDrops: [Drop] = [
        Drop(color: .black.opacity(0.10), radius: 1.5, y: 1),
        Drop(color: .black.opacity(0.10), radius: 1,   y: 1),
    ]

    /// Both drops of the `raised` level (Tailwind shadow-md).
    public static let raisedDrops: [Drop] = [
        Drop(color: .black.opacity(0.10), radius: 3, y: 4),
        Drop(color: .black.opacity(0.10), radius: 2, y: 2),
    ]

    public static let ringWidth: CGFloat = 1
}

public extension View {
    /// Card elevation: the two small drops plus the hairline ring.
    func f055CardElevation(ring: Color, radius: CGFloat) -> some View {
        self
            .shadow(color: F055Elevation.cardDrops[0].color,
                    radius: F055Elevation.cardDrops[0].radius, y: F055Elevation.cardDrops[0].y)
            .shadow(color: F055Elevation.cardDrops[1].color,
                    radius: F055Elevation.cardDrops[1].radius, y: F055Elevation.cardDrops[1].y)
            .overlay(
                RoundedRectangle(cornerRadius: radius)
                    .strokeBorder(ring, lineWidth: F055Elevation.ringWidth)
            )
    }

    /// Raised elevation: popovers, dropdowns, slider thumbs.
    func f055RaisedElevation(radius: CGFloat) -> some View {
        self
            .shadow(color: F055Elevation.raisedDrops[0].color,
                    radius: F055Elevation.raisedDrops[0].radius, y: F055Elevation.raisedDrops[0].y)
            .shadow(color: F055Elevation.raisedDrops[1].color,
                    radius: F055Elevation.raisedDrops[1].radius, y: F055Elevation.raisedDrops[1].y)
            .overlay(
                RoundedRectangle(cornerRadius: radius)
                    .strokeBorder(.black.opacity(0.10), lineWidth: F055Elevation.ringWidth)
            )
    }
}
